package com.projexa.coaching.auth.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long minutes; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.access-token-minutes:15}") long minutes){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.minutes=minutes;} public String generate(UUID userId,UUID tenantId,String email,Collection<String> authorities){Instant now=Instant.now();return Jwts.builder().subject(userId.toString()).claim("tenantId",tenantId.toString()).claim("email",email).claim("authorities",authorities).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(minutes*60))).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public long expiresIn(){return minutes*60;} }
